INSERT INTO `wp_addonlibrary_addons` VALUES
(1,'Coverflow Carousel','cover_flow_carousel_elementor','cover_flow_carousel','elementor','Discover the Coverflow Carousel Widget for Elementor. This 3D transform-based widget replicates the sleek \'cover flow\' effect, perfect for portfolios and product galleries.',1,'{\"html\":\"<div class=\\\"ue-coverflow {{remote_parent.class|raw}} {{uc_filtering_addclass}} {{uc_dynamic_popup_class}}\\\" id=\\\"{{uc_id}}\\\" {{remote_parent.attributes|raw}} {{uc_filtering_attributes|raw}}>\\n  <ul class=\\\"flip-items uc-items-wrapper\\\">\\n    {{put_items()}}\\n  <\\/ul>\\n<\\/div>\",\"html_item\":\"{% if navigation_type == \\\"title\\\" %}\\n<li class=\\\"ue-coverflow-item\\\" data-flip-title=\\\"{{item.title}}\\\">\\n{% endif %}\\n\\n{% if navigation_type == \\\"index\\\" %}\\n<li class=\\\"ue-coverflow-item\\\" data-flip-title=\\\"{{item.item_index}}\\\">\\n{% endif %}\\n  \\n  {% if show_image == \\\"true\\\" %}\\n    <div class=\\\"ue-item-image\\\">\\n      {% if item.button_link is not empty %}<a href=\\\"{{item.button_link}}\\\" {{item.button_link_html_attributes|raw}}>{% endif %}\\n        {% if item.image is empty %}\\n          <img src=\\\"{{uc_assets_url}}\\/placeholder.jpg\\\" class=\\\"{{item.item_repeater_class}} ue-coverflow-image\\\">\\n        {% else %} \\n          <img src=\\\"{{item.image}}\\\" class=\\\"{{item.item_repeater_class}} ue-coverflow-image\\\" {{item.image_attributes|raw}}> \\n        {% endif %}\\t   \\n      {% if item.button_link is not empty %}<\\/a>{% endif %}\\n    <\\/div>\\n  {% endif %}\\n  \\n  {% if show_content == \\\"true\\\" %}\\n    <div class=\\\"ue-flip-item-content {{item.item_repeater_class}}-item-content\\\">\\n      <div class=\\\"ue-flip-item-content-inside\\\">\\n        {% if show_icon == \\\"true\\\" %}<div class=\\\"ue-flip-item-icon\\\">{{item.icon_html|raw}}<\\/div>{% endif %}\\n        {% if show_title == \\\"true\\\" %}<div class=\\\"ue-flip-item-title\\\">{{item.title|raw}}<\\/div>{% endif %}\\n        {% if show_text == \\\"true\\\" %}<div class=\\\"ue-flip-item-text\\\">{{item.text|raw}}<\\/div>{% endif %}\\n        {% if show_button == \\\"true\\\" %}\\n       \\t  <div class=\\\"ue-item-btn\\\">\\n            {% if multisource != \\\"uc_items\\\" %}\\n              <a {{item.button_link_html_attributes|raw}} class=\\\"{{button_hover_animation}} ue-dynamic-popup-single {{item.dynamic_popup_link_class|raw}}\\\" {{item.dynamic_popup_link_attributes|raw}}>{{button_text|raw}}<\\/a>\\n            {% else %}\\n              <a {% if item.button_link is not empty %}href=\\\"{{item.button_link}}\\\"{% endif %} {{item.button_link_html_attributes|raw}} class=\\\"{{button_hover_animation}}\\\">{{button_text|raw}}<\\/a>\\n       \\t    {% endif %} \\n          <\\/div>\\n        {% endif %}\\n        <div class=\\\"ue-item-template\\\">{{putElementorTemplate(item.template_templateid)}}<\\/div>\\n      <\\/div>\\n    <\\/div>\\n  {% endif %}\\n<\\/li>\",\"css\":\"#{{uc_id}}{\\n  opacity: 0;\\n  min-height: 1px;\\n}\\n\\n#{{uc_id}} .flipster__item img{  \\n  display:block;\\n  width:100%;\\n}\\n\\n#{{uc_id}} .flipster__item__content{\\n  overflow:hidden;\\n  position:relative;  \\n  {% if remove_item_reflection == \\\"true\\\" %}\\n    -webkit-box-reflect: unset;\\n    box-reflect: unset;\\n  {% endif %}\\n}\\n\\n#{{uc_id}} .flipster__nav__item a{\\n  z-index:1;\\n}\\n\\n.ue-flip-item-title{\\n  font-size:21px;\\n}\\n\\n#{{uc_id}} .ue-item-btn a{\\n  text-decoration:none;\\n  text-align:center;\\n  transition:0.3s;\\n}\\n\\n{% if content_layout == \\\"overlay\\\" %}\\n   #{{uc_id}} .ue-flip-item-content    {\\n      position:absolute;\\n      top:0;\\n      left:0;\\n      right:0;\\n      bottom:0;\\n      display:flex;\\n      flex-direction:column;\\n      align-items:center;\\n      justify-content:center;\\n      transition:0.3s;\\n    }\\n{% endif %}\\n\\n#{{uc_id}} .flipster__button{\\n  line-height:1em;\\n  margin:0;\\n}\\n\\n#{{uc_id}} .ue-flip-item-icon{\\n  line-height:1em;\\n  display:inline-flex;\\n  justify-content:center;\\n  align-items:center;  \\n}\\n\\n#{{uc_id}} .ue-flip-item-icon svg{\\n  height:1em;\\n  width:1em;\\n}\\n\\n#{{uc_id}} .flipster__container, \\n#{{uc_id}} .flipster__item, \\n#{{uc_id}} .flipster__item__content{\\n  transition:{{transition_duration}}ms;\\n}\\n\\n#{{uc_id}} .flipster__nav__link::after{\\n  background-color:{{navigation_color}};\\n}\\n\\n#{{uc_id}} .flipster__nav__item a{\\n  color:{{navigation_text_color}};\\n}\\n\\n#{{uc_id}} .flipster__nav__item--current>.flipster__nav__link{\\n  color:{{navigation_text_color_selected}};\\n}\\n\\n{% if style == \\\"vertical\\\" %}\\n#{{uc_id}} {\\n  transform: rotate(90deg);\\n  overflow: unset !important;\\n}\\n#{{uc_id}} .flipster__container,\\n#{{uc_id}} .flipster__item,\\n#{{uc_id}} .flipster__item__content {\\n    transition: all 350ms ease-in-out;\\n}\\n\\n#{{uc_id}} .flipster__item {\\n    position: absolute;\\n    top: 0;\\n    left: 150px;\\n}\\n\\n#{{uc_id}} .flipster__item__content{\\n      overflow: unset !important;\\n}\\n\\n#{{uc_id}} .flipster__item__content > * { \\n  transform: rotate(-90deg); \\n}\\n  \\n#{{uc_id}} .flipster--infinite-carousel .flipster__item--future-1 .flipster__item__content{\\n    transform: translateX(30%) rotateY(0) scale(0.8) !important;\\n}\\n\\n#{{uc_id}} .flipster--infinite-carousel .flipster__item--past-1 .flipster__item__content{\\n    transform: translateX(-30%) rotateY(0) scale(0.8) !important;\\n}\\n\\n#{{uc_id}} .flipster--infinite-carousel .flipster__item--past-2 .flipster__item__content{\\n    transform: translateX(-60%) rotateY(0) scale(0.8);\\n}\\n\\n#{{uc_id}} .flipster--infinite-carousel .flipster__item--future-2 .flipster__item__content{\\n    transform: translateX(60%) rotateY(0) scale(0.8);\\n}\\n{% endif %}\",\"js\":\"{{ ucfunc(\\\"put_docready_start\\\") }}\\n\\n  var objCoverflow = jQuery(\\\"#{{uc_id}}\\\");\\n    \\n    function startCoverflow(){      \\n      objCoverflow.css(\\\"opacity\\\", 1);\\n      \\n      objCoverflow.flipster({\\n        style: \'{{style}}\',\\n        \\n        {% if style == \\\"infinite-carousel\\\" %}                  \\n        loop: 2,\\n        spacing: 0,\\n        {% elseif style == \'vertical\' %}  \\n        style: \\\"infinite-carousel\\\",\\n        buttons: false,\\n        start: 2,                    \\n        {% else %}                   \\n        loop: {{loop}}, \\n        spacing: {{spacing}},                  \\n        {% endif %}  \\n        \\n        pauseOnHover: {{pauseonhover}},\\n        \\n        {% if navigation == \\\"false\\\" %}\\n        nav: false,\\n        {% endif %}\\n        \\n        {% if navigation == \\\"before\\\" %}\\n        nav: \'before\',\\n        {% endif %}\\n        \\n        {% if navigation == \\\"after\\\" %}\\n        nav: \'after\',\\n        {% endif %}\\n        \\n        {% if autoplay == \\\"true\\\" %}\\n        autoplay: {{autoplay_timeout}},\\n        {% endif %}                        \\n        \\n        click: {{click}},\\n        keyboard: {{keyboard}},\\n        scrollwheel: {{scrollwheel}},\\n        touch: {{touch}},\\n        \\n        {% if start is not empty and style != \'vertical\'  %}\\n        start: {{start|raw}}, \\n        {% endif %}\\t\\n        \\n        {% if show_nav_arrows == \\\"true\\\" and style != \'vertical\' %}                          \\n        buttons: true,\\n        {% elseif show_nav_arrows == \\\"false\\\" and style != \'vertical\' %}   \\n        buttons: false,    \\n        {% elseif show_nav_arrows == \\\"custom\\\" and style != \'vertical\' %} \\n        buttons: \\\"custom\\\",                \\n        buttonPrev: `<i class=\'{{custom_arrow_prev}}\'><\\/i>`,\\n        buttonNext: `<i class=\'{{custom_arrow_next}}\'><\\/i>`,  \\n        {% endif %}              \\n      });\\n      \\n    }\\n    \\n    startCoverflow();\\n    \\n    objCoverflow.on(\\\"uc_ajax_refreshed\\\",function(){      \\n      \\/\\/remove flipster classes from mani container\\n      objCoverflow.removeClass(\\\"flipster flipster--transform flipster--infinite-carousel flipster--click flipster--active\\\");\\n      \\n      var objButtons = objCoverflow.find(\'.flipster__nav\');\\n      var objArrows = objCoverflow.find(\'.flipsflipster__button\');\\n      \\n      \\/\\/remove buttons and arrows\\n      objButtons.remove();\\n      objArrows.remove();\\n      \\n      \\/\\/reinit flipster\\n      startCoverflow();\\n      \\n    });\\n    \\n    var objRemoteOptions = {\\n      class_items:\\\"ue-coverflow-item\\\",\\n      class_active:\\\"flipster__item--current\\\",\\n      selector_item_trigger:\\\"\\\"\\n    };\\n    \\n    {{ucfunc(\\\"put_remote_parent_js\\\",\\\"objCoverflow\\\",\\\"objRemoteOptions\\\")}}\\n    \\n    document.addEventListener(\'animationend\', function (e) {\\n      window.dispatchEvent(new Event(\'resize\'))\\n    });     \\n    \\t\\n{{ ucfunc(\\\"put_docready_end\\\") }}\"}','{\"options\":{\"enable_items\":1,\"items_section_title\":\"\",\"items_section_heading\":\"\",\"items_title_field\":\"\",\"items_allow_empty\":\"\",\"path_assets\":\"cover_flow_carousel\",\"js_as_module\":false,\"addon_icon\":\"\",\"dynamic_addon\":\"false\",\"dynamic_post_enable_customfields\":\"false\",\"dynamic_post_enable_category\":\"false\",\"description\":\"Discover the Coverflow Carousel Widget for Elementor. This 3D transform-based widget replicates the sleek \'cover flow\' effect, perfect for portfolios and product galleries.\",\"link_resource\":\"https:\\/\\/unlimited-elements.com\\/docs\\/coverflow-carousel-for-elementor\\/\",\"link_preview\":\"https:\\/\\/unlimited-elements.com\\/coverflow-carousel-widget-for-elementor\\/\",\"show_small_icon\":\"true\",\"preview_size\":\"full\",\"preview_custom_width\":\"\",\"preview_bgcol\":\"#ffffff\",\"special\":\"\",\"special_data\":\"\",\"is_free_addon\":true,\"is_new_addon\":false,\"is_trending\":false},\"params\":[{\"type\":\"uc_slider\",\"title\":