n uc_post_grid_style_one_pagination_button\\\" aria-label=\\\"prev-btn\\\">{{prev_icon_html|raw}}<\\/button>{% endif %}\\n        <div class=\\\"uc_post_grid_style_one_pagination_numbers\\\"><\\/div>\\n        {% if show_prev_next_page_button == \\\"true\\\" %}<button class=\\\"uc_post_grid_style_one_next_button uc_post_grid_style_one_pagination_button\\\" aria-label=\\\"next-btn\\\">{{next_icon_html|raw}}<\\/button>{% endif %}\\n      <\\/div>{# end uc_post_grid_style_one_prev_button_pagination_wrap #}{##}\\n    <\\/div>{# end uc_post_grid_style_one_prev_button_pagination #}{##}\\n  {% endif %}{# end show_pagination #}{##}\\n  \\n<\\/div>\",\"html_item\":\"{# twig vars #}{##}\\n{% set buttonTextElem %}{% if item.button_text_override is empty %}{{button_text|raw}}{% else %}{{item.button_text_override|raw}}{% endif %}{% endset %}\\n{# end twig vars #}{##}\\n\\n<div class=\\\"uc_post_grid_style_one_item ue-item {% if show_pagination == \\\"true\\\" and multisource == \\\"uc_items\\\" %}ue-hidden{% endif %}\\\">\\n     \\n  {% if show_image == \\\"true\\\" %}\\n    <div class=\\\"uc_post_grid_style_one_image ue-image-holder\\\">\\n    {% if image_link == \\\"true\\\" %}\\n      {% if image_link_type == \\\"true\\\" %}\\n          <a class=\\\"uc_post_grid_style_one-link\\\" href=\\\"{{item.link|raw}}\\\" {{item.link_html_attributes|raw}} data-fancybox=\\\"gallery\\\" data-src=\\\"{{item.image}}\\\">\\n      {% else %}\\n          <a class=\\\"uc_post_grid_style_one-link\\\" {% if item.link is not empty %}href=\\\"{{item.link|raw}}\\\" {{item.link_html_attributes|raw}}{% endif %}>\\n      {% endif %}\\n    {% endif %}\\n            \\n    <img aria-role=\\\"img\\\" alt=\\\"{{item.image_alt}}\\\"  class=\\\"uc_post_image\\\" src=\\\"{{item.image}}\\\" {{item.image_attributes|ucsafe|raw}} >\\n    {% if image_link == \\\"true\\\" %}<\\/a>{% endif %}\\n    <\\/div>\\n  {% endif %}\\n  \\n  <div class=\\\"uc_content padding\\\">\\n    {% if link_full_item == \\\"true\\\" %}<a class=\\\"uc_post_grid_style_one_item_full_item_link\\\" href=\\\"{{item.link}}\\\" {{item.link_html_attributes|ucsafe|raw}}><\\/a>{% endif %}\\n    \\n    <div class=\\\"ue-content-wrapper\\\">\\n      \\n      {% if show_title == \\\"true\\\" %}\\n        {% if title_link == \\\"true\\\" and title_link_type == \\\"regular\\\" %}<a href=\\\"{{item.link|raw}}\\\" {{item.link_html_attributes|raw}}>{% endif %}\\n        {% if title_link == \\\"true\\\" and title_link_type == \\\"lightbox\\\" %}<a class=\\\"uc_post_grid_style_one-link-lightbox\\\">{% endif %}\\n        \\t<{{title_tag}} class=\\\"ue-item-title\\\">{{item.title|raw}}<\\/{{title_tag}}>\\n        {% if title_link == \\\"true\\\" %} <\\/a>{% endif %}\\n      {% endif %}\\n      \\n      {% if show_text == \\\"true\\\" %}<div class=\\\"ue-item-text\\\">{{item.content|raw}}<\\/div>{% endif %}      \\n      {% if show_description == \\\"true\\\" %}<div class=\\\"ue-item-descr\\\">{{item.item_description|raw}}<\\/div>{% endif %}\\n      \\n    <\\/div>\\n    \\n    {% if show_button == \\\"true\\\" %}\\n    \\t<div class=\\\"uc_post_grid_style_one_button ue-button\\\">\\n          {% if multisource != \\\"uc_items\\\" %}\\n            <a class=\\\"uc_more_btn {{item.dynamic_popup_link_class|raw}}\\\" \\n               {% if item.dynamic_popup_link_class|raw == \\\" uc-open-popup\\\" %}{{item.dynamic_popup_link_attributes|raw}}{% else %} href=\\\"{{item.link|raw}}\\\"{% endif %}\\n               {{item.link_html_attributes|raw}}>{{buttonTextElem}}{% if show_icon_button == \\\"true\\\" %} {{button_icon_html|raw}}{% endif %}\\n            <\\/a>\\n          {% else %}\\n           <a class=\\\"uc_more_btn\\\" href=\\\"{{item.link|raw}}\\\" {{item.link_html_attributes|raw}}>{{buttonTextElem}}{% if show_icon_button == \\\"true\\\" %}{{button_icon_html|raw}}{% endif %}<\\/a>\\n          {% endif %}\\n    \\t<\\/div>\\n    {% endif %}\\n  <\\/div>\\n<\\/div>\",\"css\":\"#{{uc_id}} * {\\n\\tbox-sizing: border-box;\\t\\n}\\n\\n#{{uc_id}} .uc_post_grid_style_one_wrap {\\n\\tdisplay: grid;\\n}\\n\\n#{{uc_id}} .uc_post_grid_style_one_image {\\t\\n\\toverflow: hidden;\\n    {% if height_type != \'ratio\' %}\\n      display: block;  \\t\\n      width: 100%;\\n    {% else %}\\n      display: inline-block;\\n    {% endif %}\\n}\\n\\n#{{uc_id}} .uc_post_image {\\n\\t{% if height_type != \'ratio\' %}\\n\\t  width: 100%;\\n      display: block;\\n    {% endif %}\\n\\theight: inherit;\\n\\tbackground-position: center center;\\n\\tbackground-repeat: no-repeat;\\n\\ttransition: all 0.25s ease-in-out;\\n}\\n\\n#{{uc_id}} .ue-image-holder a{\\n  {% if height_type != \'ratio\' %}\\n    display:block;\\n  {% endif %}\\n}\\n\\n#{{uc_id}} .ue-item{\\n  position:relative;\\n  overflow:hidden;\\n}\\n\\n#{{uc_id}} .ue-item .uc_post_grid_style_one_item_full_item_link{\\n  position: absolute;\\n  width: 100%;\\n  height: 100%;\\n  left: 0;\\n  top: 0;\\n}\\n\\n#{{uc_id}} .ue-item-title{\\n  width:100%;\\n}\\n\\n#{{uc_id}} .ue-item-text{\\n  width:100%;\\n}\\n\\n#{{uc_id}} .uc_content{\\n  display:flex;\\n  flex-direction:column;\\n}\\n\\n#{{uc_id}} .ue-content-wrapper{\\n  width:100%;\\n}\\n\\n#{{uc_id}} .ue-button{\\n  margin-top:auto;\\n}\\n\\n#{{uc_id}} .ue-button{\\n  width:100%;\\n}\\n\\n{% if show_button == \\\"true\\\" %}\\n  #{{uc_id}} a.uc_more_btn{\\n      align-items: center;\\n      justify-content: center;\\n      text-align: center;\\n      transition: all 0.25s ease-in-out;\\n  }\\n  {% if show_icon_button == \\\"true\\\" %}\\n    #{{uc_id}} a.uc_more_btn svg{\\n       width:1em;\\n       height:1em;\\n    }\\n  {% endif %}\\n{% endif %}\\n\\n{% if layout == \\\"overlay\\\" %}\\n\\t#{{uc_id}}.uc_post_grid_style_one .uc_content{\\n      position:absolute;\\n      top:0px;\\n      left:0px;\\n      bottom:0px;\\n      right:0px;\\n      opacity:0;\\n      transition:1s;\\n      display:flex;\\n      align-items:center;\\n      flex-direction:column;\\n      justify-content: center;\\n    }\\n\\n\\t#{{uc_id}} .uc_post_grid_style_one_item:hover .uc_content{\\n      opacity:1;\\n    }\\n{% endif %}\\n\\n{% if layout == \\\"partial_overlay\\\" %}\\n\\t#{{uc_id}}.uc_post_grid_style_one .uc_content{\\n     position:absolute;\\n     bottom:{{content_margin}}px;\\n     left:{{content_margin}}px;\\n     right:{{content_margin}}px;\\n    }\\n{% endif %}\\n\\n{% if layout == \\\"under_overlap\\\" %}\\n\\t#{{uc_id}}.uc_post_grid_style_one .uc_content{\\n     margin-left:20px;\\n      margin-right:20px;\\n      margin-top:-30px;\\n      position:relative;\\n    }\\n{% endif %}\\n\\n{% if layout == \\\"reveal_from_bottom\\\" %}\\n\\t#{{uc_id}}.uc_post_grid_style_one .uc_content{\\n        margin-left:0px;\\n        margin-right:0px;\\n        margin-top:0px;\\n        position:absolute;\\n      \\tbottom: -100%;\\n        left: 0;\\n        right: 0;\\n        transition: ease-in-out all 0.25s;\\n      \\t-webkit-transition: ease-in-out all 0.25s;\\n    }\\n    #{{uc_id}}.uc_post_grid_style_one .uc_post_grid_style_one_item:hover .uc_content{\\n\\t\\tbottom: 0;\\n    }\\n{% endif %}\\n\\n\\n{% if layout == \\\"side_by_side\\\" %}\\n\\t#{{uc_id}} .ue-item    {\\n      display:flex;\\n      {% if flip_side_by_side == \\\"true\\\" %}\\n      flex-direction:row-reverse;\\n      {% endif %}\\n    }\\n\\n\\t#{{uc_id}} .uc_content    {\\n      display:flex;\\n      justify-content:center;\\n      flex-direction:column;\\n      flex-shrink:0;\\n      flex-grow:0;\\n    }\\n\\n    #{{uc_id}} .ue-image-holder    {\\n      flex-grow:1;\\n    }\\n\\t\\n{% endif %}\\n\\n\\n#{{uc_id}}.uc-remote-parent .ue-item{\\n  cursor:pointer;\\n}\\n\\n#{{uc_id}} .uc_post_grid_style_one_search_wrap{\\n  display: flex;  \\n}\\n\\n#{{uc_id}} .uc_post_grid_style_one_search_container{\\n  position: relative;\\n}\\n\\n{% if disable_search_outline == \\\"true\\\" %}\\n#{{uc_id}} .uc_post_grid_style_one_search_input:focus{\\n  outline: none;\\n}\\n{% endif %}\\n\\n#{{uc_id}} ::-webkit-input-placeholder { \\/* Edge *\\/\\n  color: {{search_placeholder_color}};\\n}\\n\\n#{{uc_id}} :-ms-input-placeholder { \\/* Internet Explorer 10-11 *\\/\\n  color: {{search_placeholder_color}};\\n}\\n\\n#{{uc_id}} ::placeholder {\\n  color: {{search_placeholder_color}};\\n}\\n\\n#{{uc_id}} .uc_post_grid_style_one_next_button_pagination_button{\\n  {% if show_prev_next_page_button == \\\"false\\\" %}\\n    display: none;\\n  {% endif %}\\n}\\n\\n#{{uc_id}} .uc_post_grid_style_one_search_icon,\\n#{{uc_id}} .uc_post_grid_style_one_reset_icon{\\n\\tposition: absolute;\\n  \\ttop: 50%;\\n    transform: translate(0, -50%);\\n    height: 100%;\\n  \\tdisplay: flex;\\n    align-items: center;\\n    justify-content: center;\\n}\\n\\n#{{uc_id}} .uc_post_grid_style_one_reset_icon{\\n  cursor: pointer;\\n}\\n\\n{% if debug_reset_icon == \\\"true\\\" and uc_inside_editor == \\\"yes\\\" %}\\n  #{{uc_id}} .uc_post_grid_style_one_search_icon{\\n    display: none;\\n  }\\n  #{{uc_id}} .uc_post_grid_style_one_reset_icon{\\n    display: flex !important;\\n  }\\n{% endif %}\\n\\n\\/* pagination *\\/\\n#{{uc_id}} .uc_post_grid_style_one_prev_button_pagination{\\n  display: flex;\\n  align-items: center;\\n}\\n\\n#{{uc_id}} .uc_post_grid_style_one_pagination_button,\\n#{{uc_id}} .uc_post_grid_style_one_pagination_number{\\n  padding: 0;\\n  justify-content: center;\\n  align-items: center;\\n  transition: all .3s ease;\\n  margin: 0;\\n}\\n\\n#{{uc_id}} .uc_post_grid_style_one_pagination_number:last-child,\\n#{{uc_id}} .uc_post_grid_style_one_pagination_number:first-child{\\n  display: inline-flex;\\n  position: relative;\\n}\\n\\n#{{uc_id}} .ue-hidden{\\n  display: none;\\n}\\n\\n#{{uc_id}} .ue-disabled{\\n  opacity: .5;\\n  pointer-events: none;\\n}\\n\\n#{{uc_id}} .uc_post_grid_style_one-link-lightbox{\\n  cursor: pointer;\\n}\\n\\n#{{uc_id}} .uc_post_grid_style_one_pagination_number.ue-visible{\\n  display: inline-flex;\\n}\\n\\n#{{uc_id}} .uc_post_grid_style_one_pagination_numbers{\\n  display: flex;\\n  flex-wrap: wrap;\\n}\\n\\n#{{uc_id}} .uc_post_grid_style_one_prev_button_pagination_wrap{\\n  display: flex;\\n}\\n\\/* end pagination *\\/\\n\\n\\/* lightbox *\\/\\n\\n.fancybox-button,\\n.fancybox-button svg path{\\t\\n  color: {{navigation_icons_color}};\\n}\\n.fancybox-button{\\n  background-color: {{navigation_icons_background_color}};\\n}\\n\\n.fancybox-button:hover,\\n.fancybox-button:hover svg path{\\t\\n  color: {{navigation_icons_color_hover}};\\n}\\n.fancybox-button:hover,\\n.fancybox-button:focus{\\n  background-color: {{navigation_icons_background_color_hover}};\\n}\\n\\n.fancybox-bg{\\n  background: {{overlay_background_color}};\\n}\\n\\n.fancybox-is-open .fancybox-bg{\\n  opacity: {{overlay_opacity}} !important;\\n}\\n\\n{% if show_lightbox_counter == \\\"false\\\" %}\\n  .fancybox-infobar{\\n\\tdisplay: none !important;\\n  }\\n{% endif %}\\t\\n\\n{% if show_lightbox_zoom_button == \\\"false\\\" %}\\n  .fancybox-button--zoom{\\n\\tdisplay: none !important;\\n  }\\n{% endif %}\\t\\n\\n{% if show_lightbox_slideshow_button == \\\"false\\\" %}\\n  .fancybox-button--play{\\n\\tdisplay: none !important;\\n  }\\n{% endif %}\\t\\n\\n{% if show_lightbox_thumbnails_button == \\\"false\\\" %}\\n  .fancybox-button--thumbs{\\n\\tdisplay: none !important;\\n  }\\n{% endif %}\\t\\n\\n{% if show_lightbox_close_button == \\\"false\\\" %}\\n  .fancybox-button--close{\\n\\tdisplay: none !important;\\n  }\\n{% endif %}\\t\\n\\n{% if show_lightbox_arrows == \\\"false\\\" %}\\n  .fancybox-navigation{\\n\\tdisplay: none !important;\\n  }\\n{% endif %}\\n\\n.fancybox-caption__body{\\n  color: {{item_title_in_lightbox_color}};\\n}\\n\\n\\/* end lightbox *\\/\",\"js\":\"{{ ucfunc(\\\"put_docready_start\\\") }}\\n\\n  \\tvar objContentGrid = jQuery(\'#{{uc_id}}\');\\n\\tvar objSearch = objContentGrid.find(\\\"input\\\");\\n\\tvar objItems = objContentGrid.find(\\\".uc_post_grid_style_one_item\\\");\\n\\tvar objPaginationNumbers = objContentGrid.find(\\\".uc_post_grid_style_one_pagination_numbers\\\");\\n\\tvar pobjPaginatedList = objContentGrid.find(\\\".uc_post_grid_style_one_wrap\\\");\\n\\tvar objNextButton = objContentGrid.find(\\\".uc_post_grid_style_one_next_button\\\");\\n    var objPrevButton = objContentGrid.find(\\\".uc_post_grid_style_one_prev_button\\\");\\n\\tvar objResetButton = objContentGrid.find(\\\".uc_post_grid_style_one_reset_icon\\\");\\n  \\tvar objSearchButton = objContentGrid.find(\\\".uc_post_grid_style_one_search_icon\\\");\\n\\n\\tvar itemsPerPage = Number(\\\"{{items_number_per_page}}\\\");\\n\\tvar totalItems = objItems.length;\\n\\tvar pageCount = Math.ceil(totalItems \\/ itemsPerPage);\\n\\tvar currentPage = 1;\\n\\tvar isPagesEnabled = \\\"{{show_pagination}}\\\";\\n\\n\\tvar classActive = \\\"ue-active\\\";\\n    var classVisible = \\\"ue-visible\\\";\\n    var classDisabled = \\\"ue-disabled\\\";\\n    var classHidden = \\\"ue-hidden\\\";\\n\\tvar classSelected = \\\"ue-selected\\\";\\n\\tvar classPageNumber = \\\"uc_post_grid_style_one_pagination_number\\\";\\n\\n\\t\\/*\\n    * click on fancy title link\\n    *\\/\\n    function onTitleLighboxLinkClick(){\\n      var objTitle = jQuery(this);\\n      var objItem = objTitle.closest(\\\".ue-item\\\");\\n      var objFancyLink = objItem.find(\\\"[data-fancybox=\'gallery\']\\\");\\n          \\n      if(objFancyLink && objFancyLink.length > 0)\\n        objFancyLink.trigger(\\\"click\\\");\\n    }\\n  \\n  \\t\\/**\\n    * use fancybox\\n    *\\/\\n  \\tfunction initFancybox(){    \\n      var useFancybox = objContentGrid.data(\\\"lightbox\\\");\\n\\n      if(useFancybox == false)\\n      return(false);      \\n       \\n      var itemsNum = objItems.length;\\n\\n      \\/\\/set data index for each origin item\\n      for(let i=0; i<itemsNum; i++){\\n\\n        var objItem = objItems.eq(i);\\n        \\n        {% if show_item_title_in_lightbox == \\\"true\\\" %}\\n          var objTitle = objItem.find(\\\".ue-item-title\\\");\\n\\t\\t\\n          if(objTitle && objTitle.length > 0){\\n              var titleText = objTitle.text();\\n              var objLink = objItem.find(\'.uc_post_grid_style_one-link\');\\n            \\n              objLink.attr(\'data-caption\', titleText);\\n          }\\n        {% endif %}\\n             \\n      }\\n\\n      var fancyLinks = objContentGrid.find(\\\".uc_post_grid_style_one-link\\\");\\n\\n      fancyLinks.fancybox({\\n         loop: true,\\n         arrows : true,\\n         backfocus: false,\\n         btnTpl: {\\n           arrowLeft: `<button data-fancybox-prev class=\\\"fancybox-button fancybox-button--arrow_left\\\" title=\\\"prev\\\">` +\\n           `<div>{{previous_arrow_icon_html|raw}}<\\/div>` +\\n           `<\\/button>`,\\n           arrowRight: `<button data-fancybox-next class=\\\"fancybox-button fancybox-button--arrow_right\\\" title=\\\"next\\\">` +\\n           `<div>{{next_arrow_icon_html|raw}}<\\/div>` +\\n           `<\\/button>`,\\n         },\\n         {% if disable_zoom_in_after_lightbox_image_click == \\\"true\\\" %}\\n           clickContent: \\\"next\\\",\\n         {% endif %}\\n      }); \\n         \\n      {% if image_link_type == \\\"true\\\" and title_link_type == \\\"lightbox\\\" %}   \\n        var objTitleLinks = objContentGrid.find(\\\".uc_post_grid_style_one-link-lightbox\\\");\\n       \\n        objTitleLinks.on(\\\"click\\\", onTitleLighboxLinkClick);\\n      {% endif %}\\n    }\\n\\n    \\/**\\n    * enable reset buton\\n    *\\/\\n\\tfunction enableResetButton(){\\n      objResetButton.removeClass(classHidden);\\n      objSearchButton.addClass(classHidden);\\n    }\\n\\n\\t\\/**\\n    * disable reset buton\\n    *\\/\\n\\tfunction disableResetButton(){\\n      objResetButton.addClass(classHidden);\\n      objSearchButton.removeClass(classHidden);\\n    }\\n\\n \\t\\/**\\n    * hide reset button\\n    *\\/\\n\\tfunction onSearchInputBlur(){\\n      setTimeout(disableResetButton, 300);\\n    }\\n\\n\\t\\/**\\n    * on focus\\n    *\\/\\n\\tfunction onSearchInputFocus(){\\n      var searchValue = objSearch.val();\\n      \\n      if(searchValue != \\\"\\\")\\n      enableResetButton();\\n    }\\n\\n\\t\\/**\\n    * function for reaset button\\n    *\\/\\n\\tfunction onResetButtonClick(){\\n      objSearch.val(\\\"\\\");\\n      \\n      objSearch.trigger(\\\"input\\\")\\n    }\\n\\n \\t\\/**\\n    * scroll to top\\n    *\\/\\n    function scrollToTop(obj, num){\\n      var offsetTop = obj.offset().top;\\n\\n      jQuery(\\\"html\\\").animate({ scrollTop: (offsetTop + num) }, 500);\\n    }\\n\\n    \\/**\\n    * on input search\\n    *\\/\\n\\tfunction onSearchInput(){\\n      var value = objSearch.val().toLowerCase();\\n      \\n      \\/\\/show reset icon instead of search icon\\n      enableResetButton();\\n      \\n      objItems.each(function(index) {\\n        var objItem = jQuery(this);\\n        var titleText = objItem.find(\\\".ue-item-title\\\").text().toLowerCase(); \\/\\/ Get the title text\\n        var textText = objItem.find(\\\".ue-item-text\\\").text().toLowerCase();   \\/\\/ Get the main text\\n        var descrText = objItem.find(\\\".ue-item-descr\\\").text().toLowerCase(); \\/\\/ Get the description text\\n        var titleTextIndex = titleText.indexOf(value);\\n        var textTextIndex = textText.indexOf(value);\\n        var descrTextIndex = descrText.indexOf(value);\\n        \\n        \\/\\/ Check if the search value is found in any of the texts\\n        if (titleTextIndex > -1 || textTextIndex > -1 || descrTextIndex > -1) {\\n          objItem.removeClass(classHidden); \\/\\/ Show the item if a match is found\\n          objItem.addClass(classSelected);          \\n        } else {\\n          objItem.addClass(classHidden); \\/\\/ Hide the item if no match\\n          objItem.removeClass(classSelected);\\n        }\\n       \\n      });\\n           \\n      \\/\\/make sure that items are separated by pages after search input\\n      if(isPagesEnabled == \\\"true\\\"){\\n        var objSelectedByFilterItems = objContentGrid.find(\\\".\\\"+classSelected);\\n        var objPages = objContentGrid.find(\\\".\\\"+classPageNumber);\\n        \\n        if(!objSelectedByFilterItems || objSelectedByFilterItems.length == 0){\\n          \\/\\/remove existing pages        \\n          objPages.remove();\\n          \\n          return(true);\\n        }          \\n        \\n        var selectedItemsNum = objSelectedByFilterItems.length;\\n        \\n        \\/\\/update totalItems var\\n        totalItems = selectedItemsNum;\\n        pageCount = Math.ceil(totalItems \\/ itemsPerPage);\\n\\t\\n        \\/\\/remove existing pages        \\n        objPages.remove();\\n        \\n        \\/\\/append new amount of pages\\n        setPaginationNumbers();\\n        setCurrentPage(1, true);\\n      }\\n    }\\n\\n\\t\\/**\\n    * disable button\\n    *\\/\\n    function disableButton(objButton){\\n      objButton.addClass(classDisabled);\\n    }\\n\\n\\t\\/**\\n    * enable button\\n    *\\/\\n    function enableButton(objButton){\\n        objButton.removeClass(classDisabled);\\n    }\\n\\n\\t\\/**\\n    * handle status\\n    *\\/\\n    function handlePageButtonsStatus(){\\n      if (currentPage === 1) {\\n        disableButton(objPrevButton);\\n      } else {\\n        enableButton(objPrevButton);\\n      }\\n      \\n      if (pageCount === currentPage) {\\n        disableButton(objNextButton);\\n      } else {\\n        enableButton(objNextButton);\\n      }\\n      \\n      setTimeout(function(){\\n      \\tvar objPages = objContentGrid.find(\\\".\\\"+classPageNumber);\\n     \\n        if(!objPages || objPages.length == 0){\\n          disableButton(objPrevButton);\\n          disableButton(objNextButton);\\n        } \\n      },300);      \\n    }\\n\\n\\t\\/**\\n    * handle active state\\n    *\\/\\n    function handleActivePageNumber(){\\n      const pagesNum = document.querySelectorAll(\\\".\\\"+classPageNumber).length;\\n      \\n      document.querySelectorAll(\\\".\\\"+classPageNumber).forEach((button) => {\\n        button.classList.remove(classActive);\\n        button.classList.remove(classVisible); \\n        \\n        const pageIndex = Number(button.getAttribute(\\\"page-index\\\"));\\n        \\n        if (pageIndex == currentPage) {\\n          button.classList.add(classActive);        \\n        }        \\n      });\\n    }\\n\\n \\t\\/*\\n    ** append nums\\n    *\\/\\n    function appendPageNumber(index){\\n      const pageNumber = document.createElement(\\\"button\\\");\\n      pageNumber.className = classPageNumber;\\n      pageNumber.innerHTML = index;\\n      pageNumber.setAttribute(\\\"page-index\\\", index);\\n      pageNumber.setAttribute(\\\"aria-label\\\", \\\"Page \\\" + index);\\n      \\n      objPaginationNumbers[0].appendChild(pageNumber);\\n    }\\n\\n\\t\\/**\\n    * returns pages num\\n    *\\/\\n    function setPaginationNumbers(){\\n      for (let i = 1; i <= pageCount; i++) {\\n        appendPageNumber(i);\\n      }\\n    }\\n\\n\\t\\/**\\n    * sets current page\\n    *\\/\\n    function setCurrentPage(pageNum, isFiltered, isScrollToTop){\\n      currentPage = Number(pageNum);\\n    \\n      handleActivePageNumber();\\n      handlePageButtonsStatus();\\n\\n      const prevRange = (pageNum - 1) * itemsPerPage;\\n      const currRange = pageNum * itemsPerPage;\\n\\n      \\/\\/ Get the filtered items if isFiltered is true\\n      let itemsToDisplay;\\n\\n      if (isFiltered) {\\n          itemsToDisplay = objItems.filter(\'.\'+classSelected);\\n      } else {\\n          itemsToDisplay = objItems;\\n      }\\n\\n      \\/\\/ Calculate total number of filtered items\\n      const totalFilteredItems = itemsToDisplay.length;\\n\\n      \\/\\/ Hide all items first\\n      objItems.each(function(index, item) {\\n          item.classList.add(classHidden);\\n      });\\n\\n      \\/\\/ Show filtered items if available\\n      if (isFiltered && totalFilteredItems > 0) {\\n          itemsToDisplay.each(function(index, item) {\\n              \\/\\/ Check if the index falls within the current page range\\n              if (index >= prevRange && index < currRange) {\\n                  item.classList.remove(classHidden); \\/\\/ Show the item if it\'s in range\\n              }\\n          });\\n      } else {\\n          \\/\\/ If no filtering or no filtered items, show all items in range\\n          objItems.each(function(index, item) {\\n              if (index >= prevRange && index < currRange) {\\n                  item.classList.remove(classHidden); \\/\\/ Show the item if it\'s in range\\n              }\\n          });\\n      }\\n      \\n      if(isScrollToTop)\\n      scrollToTop(objContentGrid, -80, false);\\n    }; \\n  \\n\\t\\/\\/init fancy box\\n  \\tinitFancybox();\\n\\n \\tif(isPagesEnabled == \\\"true\\\" && `{{multisource}}` == \\\"uc_items\\\"){\\n      setPaginationNumbers();\\n      setCurrentPage(1, true, false);\\n      \\n      \\/\\/init events\\n      objPrevButton.on(\\\"click\\\", function(){\\n        setCurrentPage(currentPage - 1, true, true);\\n      });\\n      \\n      objNextButton.on(\\\"click\\\", function(){\\n        setCurrentPage(currentPage + 1, true, true);\\n      });\\n      \\n      objContentGrid.on(\\\"click\\\", \\\".\\\"+classPageNumber, function(){\\n        var objButton = jQuery(this);\\n        var pageIndex = objButton.attr(\\\"page-index\\\");\\n        \\n        if(pageIndex){\\n          setCurrentPage(pageIndex, true, true);\\n        }\\n  \\t  });     \\n    }\\n  \\n\\t\\/\\/init events\\n  \\tobjContentGrid.on(\\\"uc_ajax_refreshed\\\",function(){      \\n      initFancybox();     \\n    });\\n\\n\\tif(\\\"{{show_live_search}}\\\" && `{{multisource}}` == \\\"uc_items\\\"){\\n      objSearch.on(\\\"input\\\", onSearchInput);\\t  \\n      objSearch.on(\\\"focus\\\", onSearchInputFocus);\\n      objResetButton.on(\\\"click\\\", onResetButtonClick);\\n   